// ATTACK 1 — Authentication bypass
// username = ' OR '1'='1
// Query becomes: SELECT * FROM users WHERE username = '' OR '1'='1'
// '1'='1' is always true → returns ALL users

// ATTACK 2 — Dump entire table
// username = '; SELECT * FROM users; --
// Query becomes: SELECT * FROM users WHERE username = '';
//               SELECT * FROM users; --'
// Drops first query, runs second → all user records

// ATTACK 3 — Drop a table
// username = '; DROP TABLE users; --
// This is a 'classic' but usually fails on modern DBs with limited user perms

// ATTACK 4 — Union attack (exfiltrate other tables)
// username = ' UNION SELECT username, password, email FROM admin_users --
// Appends results from admin_users to the original query

// SAFE: parameterized query with pg (node-postgres)
import { Pool } from 'pg';
const db = new Pool();

app.get('/user', async (req, res) => {
  const { username } = req.query;

  // $1 is a placeholder — the value is passed separately
  // The database driver escapes it automatically
  // Even if username = "' OR '1'='1", it is treated as a LITERAL STRING
  const result = await db.query(
    'SELECT id, username, email FROM users WHERE username = $1',
    [username]  // Value passed separately, never interpolated into SQL
  );

  res.json(result.rows[0] ?? null);
});

// The database sees:
// SQL: SELECT id, username, email FROM users WHERE username = $1
// Parameters: ["' OR '1'='1"]
// It looks for a user with the literal name "' OR '1'='1" — finds none
// The injection payload is never parsed as SQL

// Other database drivers:
// MySQL (mysql2):   db.query('SELECT * FROM users WHERE id = ?', [id])
// SQLite (better-sqlite3): db.prepare('SELECT * FROM users WHERE id = ?').get(id)
// Prisma:           prisma.user.findUnique({ where: { id } })  // always safe

// Prisma — all queries are parameterized automatically
import { PrismaClient } from '@prisma/client';
const prisma = new PrismaClient();

// SAFE — Prisma generates parameterized SQL
const user = await prisma.user.findUnique({
  where: { username: req.query.username },
  select: { id: true, username: true, email: true },
});

// DANGEROUS EVEN WITH PRISMA — raw SQL query
// If you bypass the ORM, you bypass the protection
const result = await prisma.$queryRaw(
  `SELECT * FROM users WHERE username = '${req.query.username}'`  // ← VULNERABLE
);

// Safe raw query with Prisma (use Prisma.sql template literal):
import { Prisma } from '@prisma/client';
const result = await prisma.$queryRaw(
  Prisma.sql`SELECT * FROM users WHERE username = ${req.query.username}`
  // Prisma.sql is a tagged template that parameterizes automatically
);

